/**
 * OptionChainTab.jsx
 * Option chain analysis with pricing ladders
 */

import React, { useState } from 'react';
import { Layers, FileSpreadsheet, Eye, EyeOff } from 'lucide-react';
import { useOptionPricing } from '../../../hooks/useOptionPricing';
import { useOptionLadder } from '../../../hooks/useOptionLadder';
import * as XLSX from 'xlsx';

const OptionChainTab = () => {
  const {
    parameters,
    updateParameter,
    calculateOptionPrice,
    calculateGreeks
  } = useOptionPricing();

  const {
    ladderConfig,
    updateLadderConfig,
    isExpanded,
    setIsExpanded,
    availableGreeks,
    toggleGreek,
    generateLadder,
    ladderValidation,
    formatExpiration,
    formatPrice,
    formatPercentage
  } = useOptionLadder(calculateOptionPrice, calculateGreeks);

  // Export option chain to Excel
  const exportToExcel = () => {
    if (!ladderValidation.isValid) return;

    const ladder = generateLadder(parameters);
    const wb = XLSX.utils.book_new();

    // Option chain data
    const chainData = [
      ['Strike', 'Call Price', 'Call Delta', 'Call Theta', 'Put Price', 'Put Delta', 'Put Theta', 'Gamma', 'Vega'],
      ...ladder.map(row => [
        row.strike,
        row.callPrice,
        row.callDelta,
        row.callTheta,
        row.putPrice,
        row.putDelta,
        row.putTheta,
        row.gamma,
        row.vega
      ])
    ];

    const ws = XLSX.utils.aoa_to_sheet(chainData);
    XLSX.utils.book_append_sheet(wb, ws, 'Option Chain');

    // Parameters sheet
    const paramsData = [
      ['Parameter', 'Value'],
      ['Underlying Price', parameters.S],
      ['Risk-Free Rate', `${(parameters.r * 100).toFixed(2)}%`],
      ['Volatility', `${(parameters.sigma * 100).toFixed(2)}%`],
      ['Time to Expiry', `${parameters.T} years`],
      ['Dividend Yield', `${(parameters.q * 100).toFixed(2)}%`]
    ];

    const paramsWs = XLSX.utils.aoa_to_sheet(paramsData);
    XLSX.utils.book_append_sheet(wb, paramsWs, 'Parameters');

    XLSX.writeFile(wb, `option_chain_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const ladder = ladderValidation.isValid ? generateLadder(parameters) : [];

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 mb-6">
        <Layers className="w-6 h-6 text-red-600" />
        <h2 className="text-2xl font-semibold">Option Chain Analysis</h2>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Configuration Panel */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold mb-4">Chain Configuration</h3>

          {/* Market Parameters */}
          <div>
            <label className="block text-sm font-medium mb-2">Underlying Price</label>
            <input
              type="number"
              value={parameters.S}
              onChange={(e) => updateParameter('S', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="100"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Volatility (%)</label>
            <input
              type="number"
              value={parameters.sigma * 100}
              onChange={(e) => updateParameter('sigma', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="20"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Time to Expiry (Years)</label>
            <input
              type="number"
              value={parameters.T}
              onChange={(e) => updateParameter('T', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="0.25"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Risk-Free Rate (%)</label>
            <input
              type="number"
              value={parameters.r * 100}
              onChange={(e) => updateParameter('r', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="5"
              step="0.01"
            />
          </div>

          {/* Ladder Configuration */}
          <hr className="my-4" />

          <div>
            <label className="block text-sm font-medium mb-2">Strike Range</label>
            <div className="grid grid-cols-2 gap-2">
              <input
                type="number"
                value={ladderConfig.strikeMin}
                onChange={(e) => updateLadderConfig('strikeMin', parseFloat(e.target.value) || 0)}
                className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
                placeholder="Min"
              />
              <input
                type="number"
                value={ladderConfig.strikeMax}
                onChange={(e) => updateLadderConfig('strikeMax', parseFloat(e.target.value) || 0)}
                className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
                placeholder="Max"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Strike Step</label>
            <input
              type="number"
              value={ladderConfig.strikeStep}
              onChange={(e) => updateLadderConfig('strikeStep', parseFloat(e.target.value) || 1)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="1"
              step="0.5"
            />
          </div>

          <button
            onClick={exportToExcel}
            disabled={!ladderValidation.isValid}
            className="w-full flex items-center justify-center gap-2 bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white py-2 px-4 rounded-lg transition-colors"
          >
            <FileSpreadsheet className="w-4 h-4" />
            Export to Excel
          </button>
        </div>

        {/* Option Chain Table */}
        <div className="lg:col-span-2">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold">Option Chain</h3>
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className="flex items-center gap-1 text-red-600 hover:text-red-700"
            >
              {isExpanded ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              {isExpanded ? 'Collapse' : 'Expand'}
            </button>
          </div>

          {!ladderValidation.isValid ? (
            <div className="bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-800 p-4 rounded-lg">
              <p className="text-yellow-800 dark:text-yellow-200 text-sm">
                Please configure the market parameters and strike range to generate the option chain.
              </p>
            </div>
          ) : (
            <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-700">
                    <tr>
                      <th className="px-4 py-3 text-left font-medium">Strike</th>
                      <th className="px-4 py-3 text-right font-medium">Call Price</th>
                      {availableGreeks.delta && <th className="px-4 py-3 text-right font-medium">Call Δ</th>}
                      {availableGreeks.theta && <th className="px-4 py-3 text-right font-medium">Call Θ</th>}
                      <th className="px-4 py-3 text-right font-medium">Put Price</th>
                      {availableGreeks.delta && <th className="px-4 py-3 text-right font-medium">Put Δ</th>}
                      {availableGreeks.theta && <th className="px-4 py-3 text-right font-medium">Put Θ</th>}
                      {availableGreeks.gamma && <th className="px-4 py-3 text-right font-medium">Γ</th>}
                      {availableGreeks.vega && <th className="px-4 py-3 text-right font-medium">ν</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-600">
                    {ladder.slice(0, isExpanded ? ladder.length : 10).map((row, index) => (
                      <tr key={index} className={row.strike === parameters.S ? 'bg-blue-50 dark:bg-blue-900/20' : ''}>
                        <td className="px-4 py-3 font-medium">${formatPrice(row.strike)}</td>
                        <td className="px-4 py-3 text-right">${formatPrice(row.callPrice)}</td>
                        {availableGreeks.delta && <td className="px-4 py-3 text-right">{(row.callDelta || 0).toFixed(3)}</td>}
                        {availableGreeks.theta && <td className="px-4 py-3 text-right">{(row.callTheta || 0).toFixed(3)}</td>}
                        <td className="px-4 py-3 text-right">${formatPrice(row.putPrice)}</td>
                        {availableGreeks.delta && <td className="px-4 py-3 text-right">{(row.putDelta || 0).toFixed(3)}</td>}
                        {availableGreeks.theta && <td className="px-4 py-3 text-right">{(row.putTheta || 0).toFixed(3)}</td>}
                        {availableGreeks.gamma && <td className="px-4 py-3 text-right">{(row.gamma || 0).toFixed(4)}</td>}
                        {availableGreeks.vega && <td className="px-4 py-3 text-right">{(row.vega || 0).toFixed(3)}</td>}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {!isExpanded && ladder.length > 10 && (
                <div className="px-4 py-2 bg-gray-50 dark:bg-gray-700 text-center text-sm text-gray-600 dark:text-gray-400">
                  Showing 10 of {ladder.length} strikes. Click "Expand" to see all.
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default OptionChainTab;
